// Merge inputs from either Schedule or Manual Webhook
const scheduledItem = $('Schedule: Every Friday 8PM').all();
const webhookItem = $('Webhook - Manual PDF Request').all();

const source = webhookItem.length > 0 ? webhookItem[0] : scheduledItem[0];
const userEmail = source.json?.userEmail || 'admin@mwijay.app';
const userName = source.json?.userName || 'Mwijay User';
const journals = source.json?.data?.journals || [];
const expenses = source.json?.data?.expenses || [];

// Build HTML content for PDF
const totalIncome = expenses.filter(e => e.type === 'income').reduce((s, e) => s + (e.amount || 0), 0);
const totalExpense = expenses.filter(e => e.type === 'expense').reduce((s, e) => s + (e.amount || 0), 0);
const net = totalIncome - totalExpense;

const journalRows = journals.slice(0, 10).map(j =>
  `<tr><td>${new Date(j.date).toLocaleDateString()}</td><td>${j.title || 'Untitled'}</td><td>${j.type || '-'}</td><td>${j.mood || '-'}/5</td></tr>`
).join('');

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset='UTF-8'/>
<style>
  body { font-family: Inter, Arial, sans-serif; color: #1e293b; margin: 40px; }
  h1 { color: #FFBC2D; font-size: 28px; font-weight: 900; text-transform: uppercase; letter-spacing: 0.1em; }
  h2 { color: #0f172a; font-size: 16px; font-weight: 700; margin-top: 32px; border-bottom: 2px solid #FFBC2D; padding-bottom: 8px; }
  .meta { color: #64748b; font-size: 12px; margin-top: -8px; margin-bottom: 24px; }
  .stat-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; margin: 16px 0; }
  .stat { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; }
  .stat-value { font-size: 24px; font-weight: 900; color: #0f172a; }
  .stat-label { font-size: 11px; color: #64748b; text-transform: uppercase; letter-spacing: 0.1em; }
  .positive { color: #16a34a; } .negative { color: #dc2626; }
  table { width: 100%; border-collapse: collapse; margin-top: 16px; font-size: 13px; }
  th { background: #0f172a; color: #FFBC2D; padding: 10px 12px; text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
  td { padding: 10px 12px; border-bottom: 1px solid #e2e8f0; }
  tr:nth-child(even) { background: #f8fafc; }
  .footer { margin-top: 48px; font-size: 11px; color: #94a3b8; text-align: center; border-top: 1px solid #e2e8f0; padding-top: 16px; }
</style>
</head>
<body>
  <h1>Mwijay Note</h1>
  <div class='meta'>Weekly Report for ${userName} — Generated on ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>

  <h2>📊 Financial Overview (This Week)</h2>
  <div class='stat-grid'>
    <div class='stat'><div class='stat-value positive'>KES ${totalIncome.toLocaleString()}</div><div class='stat-label'>Total Income</div></div>
    <div class='stat'><div class='stat-value negative'>KES ${totalExpense.toLocaleString()}</div><div class='stat-label'>Total Expenses</div></div>
    <div class='stat'><div class='stat-value ${net >= 0 ? 'positive' : 'negative'}'>KES ${net.toLocaleString()}</div><div class='stat-label'>Net Balance</div></div>
  </div>

  <h2>📓 Recent Journal Entries</h2>
  <table>
    <tr><th>Date</th><th>Title</th><th>Type</th><th>Mood</th></tr>
    ${journalRows || '<tr><td colspan="4">No entries this week</td></tr>'}
  </table>

  <div class='footer'>Mwijay Note: Prestige OS — Your Digital Brain | Generated by n8n Automation</div>
</body>
</html>
`;

return [{ json: { html, userEmail, userName } }];
